// The syntax of the source in ONE place (spec 0002, "plan contract for effects" and F3): the Element properties,
// the scene id, the effects line (verbs, anchors, events, edges, offsets, absolute times) and the release-1 forms
// that are rejected. The parser (`elements.ts`, `effects.ts`, `story.ts`), the linter (`@reebeat/lint`) and the
// grammar document (`docs/grammar/effects.md`, generated by `grammarDoc.ts`) are derived from this file and from the
// closed vocabularies of `plan.ts`; nothing else spells the syntax. Plain data and plain functions.
import { Array as Arr, Record, Schema } from "effect";

import {
  CellSchema,
  ElementClassSchema,
  cells,
  edges,
  elementClasses,
  elementEvents,
  idPattern,
  sfxNames,
  verbs,
} from "./plan.ts";
import type { Anchor, Verb } from "./plan.ts";

/** An identifier: a Scene, an Element or an effect. */
export const IdentifierSchema = Schema.String.check(
  Schema.isPattern(idPattern)
);

/** Words the anchor grammar uses as its first word; no Element or effect may carry one of these ids. */
export const reservedIds = ["scene", "transition", "word"] as const;

/** The `key=value` properties of an Element line: one Schema per key, decoded from the text after `=`. */
export const propertySchemas = {
  cell: CellSchema,
  class: ElementClassSchema,
  id: IdentifierSchema,
  visible: Schema.Literals(["true", "false"]),
} as const;

export type PropertyKey = keyof typeof propertySchemas;

/** One row of the Element property table of the document. */
export interface PropertySpec {
  readonly default: string | undefined;
  /** A valid value, for the message that suggests a whole line (the Element's own id is taken from its text). */
  readonly example: string;
  /** What an open set looks like (a property with no closed set of `values`). */
  readonly form: string;
  readonly key: PropertyKey;
  readonly required: boolean;
  readonly summary: string;
  /** The closed set of values; empty for an open set. */
  readonly values: readonly string[];
}

